async function createPayment(input: PaymentInput, key: string) {
  const existing = await db.idempotency.findUnique({ where: { key } });
  if (existing) return existing.response;

  const payment = await db.payment.create({ data: input });
  await db.idempotency.create({ data: { key, response: payment } });
  return payment;
}

async function handle(entry: Entry) {
  await doBusinessChange(entry.payload);
  await redis.xAck('jobs', 'workers', entry.id);
}

async function poll() {
  const entries = await redis.xReadGroup('workers', 'alice', { key: 'jobs', id: '>' });
  for (const entry of entries) {
    await handle(entry);
  }
}

async function onOrderPaid(order: Order) {
  await db.orders.update({
    where: { id: order.id },
    data: { status: "paid" },
  });

  const endpoint = await db.endpoints.findFirstOrThrow({
    where: { merchantId: order.merchantId },
  });

  await postWebhook(endpoint.url, { event: "order.paid", data: order });
}

async function postWebhook(url: string, payload: unknown) {
  const body = JSON.stringify(payload);
  const res = await fetch(url, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      "x-signature": createHmac("sha256", SECRET).update(body).digest("hex"),
    },
    body,
  });

  if (!res.ok) {
    return postWebhook(url, payload);
  }
}
